// ─── File: src/main/java/com/bank/notify/service/NotificationService.java ───
package com.bank.notify.service;

import com.bank.notify.dto.NotificationEmail;
import com.bank.notify.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;

@Service
@Slf4j
public class NotificationService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "SAV2001", "RELIANCE", "BUY",  new java.math.BigDecimal("245050"), "SETTLED"),
        new Trade("TRD-002", "SAV2001", "TCS",      "BUY",  new java.math.BigDecimal("176000"), "SETTLED"),
        new Trade("TRD-003", "SAV2001", "HDFC",     "SELL", new java.math.BigDecimal("330150"), "SETTLED"),
        new Trade("TRD-004", "SAV2001", "INFY",     "BUY",  new java.math.BigDecimal("222037"), "SETTLED")
    );

    public NotificationEmail buildNotification(String accountId) {
        List<Trade> accountTrades = trades.stream()
            .filter(t -> t.accountId().equals(accountId))
            .toList();

        // ═══ 1. joining(", ") — CSV of trade IDs ═══
        String tradeIdsCsv = accountTrades.stream()
            .map(Trade::tradeId)
            .collect(Collectors.joining(", "));
        // "TRD-001, TRD-002, TRD-003, TRD-004"
        log.info("Trade IDs CSV: {}", tradeIdsCsv);

        // ═══ 2. joining(", ") — CSV of unique symbols ═══
        String symbolsCsv = accountTrades.stream()
            .map(Trade::symbol)
            .distinct()
            .sorted()
            .collect(Collectors.joining(", "));
        // "HDFC, INFY, RELIANCE, TCS"

        // ═══ 3. joining(", ", "[", "]") — wrapped list ═══
        String wrappedSymbols = accountTrades.stream()
            .map(Trade::symbol)
            .distinct()
            .sorted()
            .collect(Collectors.joining(", ", "Traded symbols: [", "]"));
        // "Traded symbols: [HDFC, INFY, RELIANCE, TCS]"

        // ═══ 4. joining for JSON-like array ═══
        String tradeSummary = accountTrades.stream()
            .map(t -> "{\"id\":\"" + t.tradeId() + "\",\"symbol\":\"" + t.symbol()
                + "\",\"amount\":" + t.amount() + "}")
            .collect(Collectors.joining(",\n  ", "[\n  ", "\n]"));
        // Produces formatted JSON array

        // ═══ 5. joining as downstream in groupingBy ═══
        Map<String, String> tradeIdsBySide = accountTrades.stream()
            .collect(Collectors.groupingBy(Trade::side,
                Collectors.mapping(Trade::tradeId,
                    Collectors.joining(", ", "(", ")"))));
        // {BUY: "(TRD-001, TRD-002, TRD-004)", SELL: "(TRD-003)"}
        log.info("By side: {}", tradeIdsBySide);

        // ═══ 6. Manual StringBuilder equivalent (what joining replaces) ═══
        StringBuilder sb = new StringBuilder("Traded symbols: [");
        List<String> symbols = accountTrades.stream()
            .map(Trade::symbol).distinct().sorted().toList();
        for (int i = 0; i < symbols.size(); i++) {
            if (i > 0) sb.append(", ");  // manual delimiter logic!
            sb.append(symbols.get(i));
        }
        sb.append("]");
        String manualResult = sb.toString();
        // Same result as wrappedSymbols — but 6 lines instead of 1!

        // ═══ 7. Empty stream handling ═══
        String emptyHandling = Stream.<String>empty()
            .collect(Collectors.joining(", ", "Trades: [", "]"));
        // "Trades: []" — prefix+suffix only, no delimiter, no elements

        return new NotificationEmail(accountId, tradeIdsCsv, symbolsCsv,
            wrappedSymbols, tradeSummary, tradeIdsBySide,
            manualResult, emptyHandling);
    }
}
```

