// ─── File: src/test/java/com/bank/notify/service/JoiningCollectorTest.java ───
package com.bank.notify.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class JoiningCollectorTest {

    @Test
    void joiningNoDelimiter() {
        String result = Stream.of("RELIANCE", "TCS", "HDFC")
            .collect(Collectors.joining());
        assertThat(result).isEqualTo("RELIANCETCSHDFC");
    }

    @Test
    void joiningWithDelimiter() {
        String result = Stream.of("RELIANCE", "TCS", "HDFC")
            .collect(Collectors.joining(", "));
        assertThat(result).isEqualTo("RELIANCE, TCS, HDFC");
    }

    @Test
    void joiningWithPrefixSuffix() {
        String result = Stream.of("RELIANCE", "TCS", "HDFC")
            .collect(Collectors.joining(", ", "[", "]"));
        assertThat(result).isEqualTo("[RELIANCE, TCS, HDFC]");
    }

    @Test
    void joiningSingleElement() {
        String result = Stream.of("RELIANCE")
            .collect(Collectors.joining(", ", "[", "]"));
        assertThat(result).isEqualTo("[RELIANCE]");  // no delimiter for single element
    }

    @Test
    void joiningEmptyStream() {
        String result = Stream.<String>empty()
            .collect(Collectors.joining(", ", "[", "]"));
        assertThat(result).isEqualTo("[]");  // prefix + suffix only
    }

    @Test
    void joiningEmptyStreamNoWrapper() {
        String result = Stream.<String>empty()
            .collect(Collectors.joining(", "));
        assertThat(result).isEmpty();  // empty string for empty stream
    }

    @Test
    void joiningAsDownstreamInGroupingBy() {
        record Item(String category, String name) {}
        var items = List.of(new Item("BUY", "T1"), new Item("BUY", "T2"), new Item("SELL", "T3"));

        Map<String, String> grouped = items.stream()
            .collect(Collectors.groupingBy(Item::category,
                Collectors.mapping(Item::name, Collectors.joining(", ", "(", ")"))));

        assertThat(grouped).containsEntry("BUY", "(T1, T2)");
        assertThat(grouped).containsEntry("SELL", "(T3)");
    }

    @Test
    void joiningBetterThanManualStringBuilder() {
        List<String> symbols = List.of("RELIANCE", "TCS", "HDFC");

        // Manual: 5 lines
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < symbols.size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(symbols.get(i));
        }
        sb.append("]");

        // Joining: 1 line
        String joining = symbols.stream().collect(Collectors.joining(", ", "[", "]"));

        assertThat(sb.toString()).isEqualTo(joining);  // same result!
    }
}
